def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    for pos in range(n.bit_length() - 1, -1, -1):
        if (n & (1 << pos)) == 0:
            return n | (1 << pos)

    return n

assert set_left_most_unset_bit(10) == 14
